mapper.select:
SELECT tf.project_id 'project.id', cp.name 'project.name', cp.short_name 'project.short_name', cp.serial_number 'project.serial_number'
,tf.testing_fee_type_id, type.label testing_fee_type_name
FROM contract_testing_fee tf LEFT JOIN sys_dictionary type ON tf.testing_fee_type_id = type.id AND type.bool_delete_enum = 0 LEFT JOIN contract_project cp ON tf.project_id = cp.id AND cp.bool_delete_enum = 0 WHERE tf.bool_delete_enum = 0 AND tf.project_id is not null AND tf.`year` = #{year}
AND tf.project_id = #{projectId}
AND tf.testing_fee_type_id = #{testingFeeTypeId}
GROUP BY tf.project_id
, tf.testing_fee_type_id
